import React, { HTMLAttributes, useState } from 'react';

import { Tab, TabProps, Tabs } from 'react-bootstrap';

export interface IPohTab extends Omit<TabProps, 'content'> {
  key: any;
  title: React.ReactNode;
  content: React.ReactNode;
  disabled?: boolean;
}

interface IPohTabsProps extends HTMLAttributes<HTMLDivElement> {
  tabs: IPohTab[];
  defaultKey?: any | null;
  onChange?: (selected: any) => {};
  useHash?: boolean;
}

const PohTabs: React.FC<IPohTabsProps> = ({ tabs, defaultKey, onChange, useHash }) => {
  let defaultActive = defaultKey || tabs?.[0]?.key;
  if (useHash && window.location.hash?.length) {
    defaultActive = window.location.hash.substr(1);
  }

  const [key, setKey] = useState(defaultActive);
  const setTabHandler = (k: any) => {
    setKey(k);
    onChange?.(k);

    if (useHash) {
      window.location.hash = `#${k}`;
    }
  };

  return (
    <Tabs id={tabs.map((t) => t.key.toString()).join('_')} activeKey={key} onSelect={setTabHandler}>
      {tabs.map(({ key: tabkey, title, content, ...rest }) => (
        <Tab eventKey={tabkey} key={tabkey} title={title} {...rest}>
          {content}
        </Tab>
      ))}
    </Tabs>
  );
};

export default PohTabs;
